{
  "bioavailability_prediction": "low",
  "confidence": "high",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C06","C04","C10","C12","C05","C32","C33","C15","C49","C53","C61","C64","C70","C72"],
  "contradictory_card_ids": ["C17"],
  "prediction_basis_card_ids": ["C06","C04","C10","C12","C05","C32","C33","C15","C49","C61","C64","C70","C72"],
  "claims": [
    {
      "claim": "The query is a fully ionized dicarboxylic acid diketopiperazine (logD -5.3, TPSA 191 Å², 6 HBD/6 HBA, MW 452 Da); this physicochemical profile is consistent with the low-F contexts of acamprosate and ferulic acid.",
      "card_ids": ["C06","C05"]
    },
    {
      "claim": "Acamprosate has absolute oral bioavailability of approximately 11% in humans under fasting conditions; L5 Caco-2 records show low Papp around 1.45–1.62 ×10⁻⁷ cm/s with no consistent net efflux, supporting low absorption for a fully ionized polar acid. One conflicting report of 42% exists but is outweighed by multiple 11% absolute-F studies.",
      "card_ids": ["C06","C04","C10","C12","C61","C65","C67","C66","C17"]
    },
    {
      "claim": "Ferulic acid, a low-lipophilicity carboxylic acid, shows 3–10% oral bioavailability in humans; food-matrix comparisons do not provide absolute F evidence and do not contradict the low-F direction.",
      "card_ids": ["C05","C25","C31"]
    },
    {
      "claim": "Oseltamivir carboxylate, the polar active carboxylate, has very poor oral bioavailability and F = 4.3% in rats; high-F oseltamivir records reflect ester-prodrug masking and are not transferable to the query's free dicarboxylic acid.",
      "card_ids": ["C32","C33","C11","C16","C21"]
    },
    {
      "claim": "Tetrahydrouridine has 4.1% human bioavailability and <5% monkey bioavailability, providing additional low-F context for a polar, poorly permeable molecule.",
      "card_ids": ["C15","C26","C30"]
    },
    {
      "claim": "L5 Caco-2 records for microcystin-LR, a polar cyclic peptide-like molecule, show very low Papp (AB 2.4 ×10⁻⁸ cm/s at 2 h; BA 4.0 ×10⁻⁸ cm/s) and active transport dominating over passive diffusion, supporting low permeability and possible efflux for polar cyclic peptide-like scaffolds.",
      "card_ids": ["C72","C63","C70"]
    },
    {
      "claim": "L5 records for acamprosate show no net active transport (similar A-B and B-A Papp), gallic acid permeates via paracellular diffusion, and 3,4,3-LI(1,2-HOPO) permeation was below the limit of quantitation; these mechanistic data support low absorption but are not direct oral-bioavailability results.",
      "card_ids": ["C61","C64","C69","C71"]
    },
    {
      "claim": "L3 oral AUC/Cmax/Tmax records are for unrelated molecules (sodium oxybate, diclofenac, misoprostol, amoxicillin, melatonin) and provide no absolute or relative bioavailability evidence for the query.",
      "card_ids": ["C37","C38","C39","C40","C41","C42","C43","C44","C45","C46","C47","C48"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C61","C62","C63","C64","C65","C66","C67","C68","C69","C70","C71","C72"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability or matched oral-versus-IV exposure data exist for the query molecule.",
    "No query-specific intestinal metabolism or gut-wall efflux measurements; L5 records are for reference molecules (acamprosate, microcystin-LR, HOPO, gallic acid).",
    "L5 contains no intestinal metabolism assays; only Caco-2 permeability/efflux records were retrieved.",
    "Conflicting acamprosate report (42%) and variable indoramin data limit quantitative extrapolation.",
    "Oseltamivir carboxylate low-F evidence is from rats (4.3%) and a qualitative human 'very poor' statement; no human absolute F is available."
  ],
  "decision_summary": "Predicted low because the query is a fully ionized, extremely polar dicarboxylic acid DKP (logD -5.3, TPSA 191 Å²) with no prodrug masking; direct low-F contexts (acamprosate ~11%, ferulic acid 3–10%, oseltamivir carboxylate very poor/4.3% rat, THU 4.1% human) and L4/L5 Caco-2 permeability/efflux data for polar acids and cyclic peptide-like molecules support F < 20%; L5 mechanistic records strengthen but do not replace the direct low-F evidence."
}

